const body = $input.first().json.body || {};
const now = new Date();
const fmt = (d) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris' }).format(d);
return [{ json: {
  docId: 'cRP1WgZQv7KmwmVrUbuEF8',
  userId: Number(body.userId),
  action: (body.action || 'status').toString(),
  today: fmt(now),
  yesterday: fmt(new Date(now.getTime() - 86400000)),
  now: Math.floor(now.getTime() / 1000),
  cardId: body.cardId != null ? Number(body.cardId) : null
} }];

// Devine la carte (2026-10-04) : quiz quotidien. Chaque jour, TOUS les
// joueurs voient le meme zoom sur l'illustration d'une meme carte (tirage
// deterministe a partir de la date - de quoi en parler entre joueurs) et
// doivent retrouver son nom parmi 4 propositions. Un seul essai par jour.
// Bonne reponse : poussieres + serie (GuessStreak) ; tous les 7 jours de
// serie, un booster en plus. Mauvaise reponse : petite consolation, serie
// remise a zero.
function refId(v) { return Array.isArray(v) ? v[1] : v; }
function firstAttachment(v) { if (!Array.isArray(v) || !v.length) return null; const ids = v[0] === 'L' ? v.slice(1) : v; return ids.length ? ids[0] : null; }
function levelForXp(xp) { xp = xp || 0; return Math.floor((25 + Math.sqrt(625 + 100 * xp)) / 50); }
function toDateStr(v) { if (v == null || v === '') return null; if (typeof v === 'number') return new Date(v * 1000).toISOString().slice(0, 10); return String(v).slice(0, 10); }
// PRNG deterministe (mulberry32) seme par la date : meme carte, memes
// propositions et meme zoom pour tout le monde le meme jour.
function seeded(str) { let h = 1779033703 ^ str.length; for (let i = 0; i < str.length; i++) { h = Math.imul(h ^ str.charCodeAt(i), 3432918353); h = (h << 13) | (h >>> 19); } let a = h >>> 0; return () => { a |= 0; a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }

const REWARD_DUST = 30;
const STREAK_DUST_BONUS = 5;      // +5 poussieres par jour de serie (plafonne)
const STREAK_DUST_BONUS_MAX = 30;
const STREAK_BOOSTER_EVERY = 7;
const CONSOLATION_DUST = 5;
const XP_PER_GUESS = 5;

const cfg = $('Set Config').first().json;
const users = $('Get Users').all().map((i) => i.json).filter((r) => r.id != null);
const cards = $('Get Cards').all().map((i) => i.json).filter((r) => r.id != null);
const user = users.find((u) => u.id === cfg.userId);
if (!user) return [{ json: { ok: false, error: 'user_not_found' } }];

// Pool : cartes actives avec image, hors cartes secretes / promo / coffre
// (on ne devoile jamais une carte cachee via le quiz).
const pool = cards.filter((c) => c.Active && !c.IsSecret && !c.IsPromo && !c.IsVault && firstAttachment(c.Image) != null).sort((a, b) => a.id - b.id);
if (pool.length < 4) return [{ json: { ok: false, error: 'not_enough_cards' } }];
const rnd = seeded('guess-' + cfg.today);
const answer = pool[Math.floor(rnd() * pool.length)];
const others = pool.filter((c) => c.id !== answer.id);
const picks = [answer];
while (picks.length < 4) { const c = others.splice(Math.floor(rnd() * others.length), 1)[0]; picks.push(c); }
for (let i = picks.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [picks[i], picks[j]] = [picks[j], picks[i]]; }
// Zoom : facteur 2.6x a 3.4x, centre tire au hasard en evitant les bords.
const zoom = { scale: Math.round((2.6 + rnd() * 0.8) * 100) / 100, x: Math.round(20 + rnd() * 60), y: Math.round(20 + rnd() * 60) };

const playedToday = toDateStr(user.GuessDate) === cfg.today;
const streak = user.GuessStreak || 0;
const base = {
  date: cfg.today, imageId: firstAttachment(answer.Image), zoom,
  choices: picks.map((c) => ({ cardId: c.id, name: c.Name })),
  played: playedToday, streak, boosterEvery: STREAK_BOOSTER_EVERY
};
// La reponse n'est devoilee qu'une fois le jeu du jour joue.
const reveal = { answerCardId: answer.id, answerName: answer.Name, correct: streak > 0 };

if (cfg.action === 'status') {
  return [{ json: { ok: true, shouldUpdate: false, payload: playedToday ? { ...base, ...reveal } : base } }];
}
if (cfg.action !== 'guess') return [{ json: { ok: false, error: 'unknown_action' } }];
if (playedToday) return [{ json: { ok: false, error: 'already_played' } }];
if (!picks.some((c) => c.id === cfg.cardId)) return [{ json: { ok: false, error: 'invalid_choice' } }];

const correct = cfg.cardId === answer.id;
const continues = toDateStr(user.GuessDate) === cfg.yesterday && streak > 0;
const newStreak = correct ? (continues ? streak + 1 : 1) : 0;
const dust = correct ? REWARD_DUST + Math.min(STREAK_DUST_BONUS * (newStreak - 1), STREAK_DUST_BONUS_MAX) : CONSOLATION_DUST;
const boosters = correct && newStreak % STREAK_BOOSTER_EVERY === 0 ? 1 : 0;
const newXp = (user.XP || 0) + XP_PER_GUESS;
const levelsGained = levelForXp(newXp) - levelForXp(user.XP || 0);
const update = {
  GuessDate: cfg.today, GuessStreak: newStreak,
  StardustCount: (user.StardustCount || 0) + dust,
  BoosterCount: (user.BoosterCount || 0) + boosters + levelsGained,
  XP: newXp
};
return [{ json: {
  ok: true, shouldUpdate: true, userId: cfg.userId, update,
  payload: { ...base, played: true, streak: newStreak, answerCardId: answer.id, answerName: answer.Name, correct,
    reward: { dust, boosters, levelsGained }, newStardust: update.StardustCount, newBoosterCount: update.BoosterCount, xp: { total: newXp, level: levelForXp(newXp) } }
} }];
